"""Editable Rush approach from the same TypeScript geometry used at runtime.
Regenerate: blender --background --python-exit-code 1 --python tools/blender/build_rush_approach.py
"""
import bpy, json, subprocess, hashlib, struct
from pathlib import Path
from mathutils import Vector
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'public/defense/models'; ART=ROOT/'art-source/defense'
OUT.mkdir(parents=True,exist_ok=True); ART.mkdir(parents=True,exist_ok=True)
module=(ROOT/'src/rush/terrainElevation.ts').as_uri()
code="import {createGroundGeometry,createCliffGeometry} from "+json.dumps(module)+"; console.log(JSON.stringify([createGroundGeometry(),createCliffGeometry()].map(g=>({p:[...g.attributes.position.array],c:[...g.attributes.color.array],i:[...g.index.array]}))));"
data=json.loads(subprocess.check_output(['node','--experimental-strip-types','--input-type=module','-e',code],cwd=ROOT,text=True))
bpy.ops.object.select_all(action='SELECT'); bpy.ops.object.delete(use_global=False)
mat=bpy.data.materials.new('Arcana forest vertex colours');mat.use_nodes=True
node=mat.node_tree.nodes.new('ShaderNodeVertexColor');node.layer_name='Color';bs=mat.node_tree.nodes['Principled BSDF'];mat.node_tree.links.new(node.outputs['Color'],bs.inputs['Base Color']);bs.inputs['Roughness'].default_value=.9
objects=[]
for name,d in zip(['Walkable lower field ramp and castle plateau','Rock skirt below the boundary'],data):
    verts=[(d['p'][i],-d['p'][i+2],d['p'][i+1]) for i in range(0,len(d['p']),3)]
    faces=[d['i'][i:i+3] for i in range(0,len(d['i']),3)]
    mesh=bpy.data.meshes.new(name);mesh.from_pydata(verts,[],faces);mesh.update()
    obj=bpy.data.objects.new(name,mesh);bpy.context.collection.objects.link(obj);obj.data.materials.append(mat)
    color=mesh.color_attributes.new(name='Color',type='FLOAT_COLOR',domain='CORNER')
    for loop in mesh.loops:
        index=loop.vertex_index*3;color.data[loop.index].color=(*d['c'][index:index+3],1)
    objects.append(obj)
s=bpy.context.scene;s.render.engine='CYCLES';s.cycles.samples=16;s.cycles.use_denoising=False
s.render.threads_mode='FIXED';s.render.threads=4;s.render.resolution_x=640;s.render.resolution_y=480;s.render.resolution_percentage=100;s.render.film_transparent=True
s.view_settings.view_transform='Standard';s.view_settings.look='Medium High Contrast'
world=bpy.data.worlds.new('Arcana forest daylight');world.use_nodes=True;world.node_tree.nodes['Background'].inputs[0].default_value=(.63,.71,.76,1);world.node_tree.nodes['Background'].inputs[1].default_value=.7;s.world=world
bpy.ops.object.light_add(type='SUN',location=(-20,-20,30));bpy.context.object.rotation_euler=(.5,-.4,-.5);bpy.context.object.data.energy=2.1;bpy.context.object.data.angle=.1
bpy.ops.object.camera_add(location=(32,-42,33));camera=bpy.context.object;target=Vector((0,6.5,.4));camera.rotation_euler=(target-camera.location).to_track_quat('-Z','Y').to_euler();camera.data.type='ORTHO';camera.data.ortho_scale=57;s.camera=camera
command='blender --background --python-exit-code 1 --python tools/blender/build_rush_approach.py'
s['regeneration_command']=command;s['height_contract']='runtime Y-up: 0 for z<=1; .3*(z-1) for 1<z<5; 1.2 for z>=5; ground xz simulation unchanged'
bpy.context.preferences.filepaths.save_version=0
blend=ART/'rush-approach.blend';bpy.ops.wm.save_as_mainfile(filepath=str(blend))
png=OUT/'rush-approach.png';s.render.filepath=str(png);bpy.ops.render.render(write_still=True)
bpy.ops.object.select_all(action='DESELECT')
for o in objects:o.select_set(True)
bpy.context.view_layer.objects.active=objects[0]
glb=OUT/'rush-approach.glb';bpy.ops.export_scene.gltf(filepath=str(glb),export_format='GLB',use_selection=True,export_yup=True,export_animations=False)
webp=OUT/'rush-approach-game.webp';subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-i',str(png),'-vf','scale=320:240','-frames:v','1','-c:v','libwebp','-quality','90',str(webp)],check=True)
files=[Path(__file__),ROOT/'src/rush/terrainElevation.ts',blend,glb,png,webp]
meta={'command':command,'concept':'art-source/defense/concepts/2026-11-06/verdant-heart.png','sourceOfTruth':'src/rush/terrainElevation.ts','runtime':{'representation':'same actual vertices regenerated by Three.js; exported GLB is inspectable authoring companion','meshCount':2,'triangles':sum(len(d['i'])//3 for d in data),'rampStartZ':1,'rampEndZ':5,'plateauY':1.2,'physics':'x/z collision and damage rules unchanged; no independent 3D rigid-body physics','textureImages':False},'camera':{'positionBlender':[32,-42,33],'targetBlender':[0,6.5,.4],'orthoScale':57,'resolution':[640,480]},'bake':{'resolution':[320,240],'usage':'archival preview; not applied to 2.5D campaign'},'files':[{'path':str(f.relative_to(ROOT)),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in files]}
(OUT/'rush-approach.json').write_text(json.dumps(meta,indent=2)+'\n')
print('RUSH_APPROACH_COMPLETE',json.dumps(meta['runtime']),flush=True)
